#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> ops(q, vector<long long>(3));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> ops[i][j];
        }
    }

    long long size = 1;
    while (size < n) size *= 2;
    const long long LOW = -(1LL << 62);
    vector<long long> ts(2 * size, 0), tm(2 * size, LOW);
    for (long long i = 0; i < n; i++) ts[size + i] = tm[size + i] = a[i];
    for (long long v = size - 1; v >= 1; v--) {
        ts[v] = ts[2 * v] + ts[2 * v + 1];
        tm[v] = max(tm[2 * v], tm[2 * v + 1]);
    }
    string out;
    for (long long k = 0; k < q; k++) {
        long long kind = ops[k][0], x = ops[k][1], y = ops[k][2];
        if (kind == 1) {
            long long v = size + x - 1;
            ts[v] = tm[v] = y;
            for (v /= 2; v >= 1; v /= 2) {
                ts[v] = ts[2 * v] + ts[2 * v + 1];
                tm[v] = max(tm[2 * v], tm[2 * v + 1]);
            }
        } else {
            long long lo = size + x - 1, hi = size + y, s = 0, m = LOW;
            while (lo < hi) {
                if (lo & 1) {
                    s += ts[lo];
                    m = max(m, tm[lo]);
                    lo++;
                }
                if (hi & 1) {
                    --hi;
                    s += ts[hi];
                    m = max(m, tm[hi]);
                }
                lo /= 2;
                hi /= 2;
            }
            if (!out.empty()) out += " ";
            out += to_string(s) + " " + to_string(m);
        }
    }
    cout << out << "\n";

    return 0;
}

